"""Upload an adapter or merged model to the Hugging Face Hub with an auto-generated model card (bonus task).

    huggingface-cli login                                   # or: export HF_TOKEN=hf_...
    python -m qlora_finetune.push --path models/phi-2-samsum-qlora --repo-id salikhussain71-code/phi-2-samsum-qlora
    python -m qlora_finetune.push --path models/phi-2-samsum-merged --repo-id <user>/phi-2-samsum --public
    python -m qlora_finetune.push --path models/phi-2-samsum-qlora --dry-run     # show what would be uploaded

Repositories are **private** unless you pass ``--public``. Training checkpoints and optimiser states are never uploaded.
"""

from __future__ import annotations

import argparse
import logging
import os
import re
import sys
from pathlib import Path

from . import config
from .modelcard import build_model_card, load_json
from .presets import resolve_model_id

logger = logging.getLogger("qlora_finetune")

IGNORE = ["checkpoints/*", "checkpoints", "*.pt", "optimizer*", "train_log.csv", "__pycache__/*"]
REPO_RE = re.compile(r"^[A-Za-z0-9][\w.-]*/[\w.-]+$")


def detect_kind(path: Path) -> str:
    """``adapter`` if the folder holds a LoRA adapter, ``merged`` if it holds a full model."""
    if (path / "adapter_config.json").exists():
        return "adapter"
    if (path / "config.json").exists():
        return "merged"
    raise ValueError(f"'{path}' is neither a LoRA adapter (adapter_config.json) nor a model (config.json).")


def is_autogenerated_card(text: str) -> bool:
    """PEFT writes a generic template card (full of 'More Information Needed') when saving an adapter."""
    return "[More Information Needed]" in text


def files_to_upload(path: Path) -> list[Path]:
    skip = ("checkpoints", "__pycache__")
    return sorted(p for p in path.rglob("*") if p.is_file() and not any(part in skip for part in p.relative_to(path).parts)
                  and p.suffix != ".pt" and not p.name.startswith("optimizer") and p.name != "train_log.csv")


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="Push a model to the Hugging Face Hub.")
    p.add_argument("--path", type=Path, required=True, help="Adapter or merged-model folder.")
    p.add_argument("--repo-id", default=None, help="user/name on the Hub (default: salikhussain71-code/<folder name>).")
    p.add_argument("--public", action="store_true", help="Make the repository public (default: private).")
    p.add_argument("--token", default=None, help="Hub token (default: $HF_TOKEN or the cached `huggingface-cli login`).")
    p.add_argument("--base-model", default=None, help="Base model id for the card (default: read from the adapter).")
    p.add_argument("--dataset-id", default=config.DEFAULT_DATASET_ID)
    p.add_argument("--results-file", type=Path, default=config.METRICS_DIR / "results.json")
    p.add_argument("--training-summary", type=Path, default=config.METRICS_DIR / "training_summary.json")
    p.add_argument("--overwrite-card", action="store_true", help="Replace an existing README.md.")
    p.add_argument("--commit-message", default="Upload model")
    p.add_argument("--dry-run", action="store_true", help="Prepare everything but upload nothing.")
    return p


def main(argv: list[str] | None = None) -> int:
    p = build_parser()
    args = p.parse_args(argv)
    logging.basicConfig(level=logging.INFO, format="%(asctime)s | %(levelname)s | %(message)s", datefmt="%H:%M:%S")

    path = args.path
    if not path.is_dir():
        logger.error("Folder not found: %s", path)
        return 1
    try:
        kind = detect_kind(path)
    except ValueError as err:
        logger.error("%s", err)
        return 1
    repo_id = args.repo_id or f"salikhussain71-code/{path.name}"
    if not REPO_RE.match(repo_id):
        logger.error("Invalid --repo-id '%s' (expected 'user-or-org/name').", repo_id)
        return 1

    base_model = args.base_model
    if base_model is None and kind == "adapter":
        import json

        base_model = json.loads((path / "adapter_config.json").read_text(encoding="utf-8")).get("base_model_name_or_path")
    base_model = resolve_model_id(base_model or "unknown")

    card_path = path / "README.md"
    if args.overwrite_card or not card_path.exists() or is_autogenerated_card(card_path.read_text(encoding="utf-8")):
        card = build_model_card(kind, repo_id, base_model, args.dataset_id,
                                load_json(args.training_summary), load_json(args.results_file))
        card_path.write_text(card, encoding="utf-8")
        logger.info("Model card written to %s", card_path)
    else:
        logger.info("Keeping your existing %s (use --overwrite-card to regenerate it).", card_path)

    files = files_to_upload(path)
    total_mb = sum(f.stat().st_size for f in files) / 1e6
    print(f"{kind} -> {repo_id} ({'public' if args.public else 'private'}): {len(files)} files, {total_mb:.1f} MB")
    for f in files:
        print(f"  {f.relative_to(path)}  ({f.stat().st_size / 1e6:.2f} MB)")
    if args.dry_run:
        print("Dry run: nothing was uploaded.")
        return 0

    token = args.token or os.environ.get("HF_TOKEN")
    try:
        from huggingface_hub import HfApi

        api = HfApi(token=token)
        api.create_repo(repo_id=repo_id, private=not args.public, exist_ok=True, repo_type="model")
        api.upload_folder(folder_path=str(path), repo_id=repo_id, repo_type="model", ignore_patterns=IGNORE,
                          commit_message=args.commit_message)
    except Exception as err:   # authentication, network, permissions
        logger.error("Upload failed: %s\nLog in with `huggingface-cli login` (token with *write* access) or set "
                     "HF_TOKEN, and check the repository id.", err)
        return 1
    print(f"Done: https://huggingface.co/{repo_id}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
